#!/bin/sh
. "$MIXOMO_LIB_DIR/common.sh"

# Installs a helper that applies MagiTrickle's domain-based marks to packets
# generated by the router itself (mangle/OUTPUT), plus its UI toggle and state.
magitrickle_local_install() {
    ensure_dir /usr/local/sbin || return 1

    install_text_atomic "$MIXOMO_SOURCE_ROOT/src/runtime/magitrickle-local/magitrickle-local.sh" \
        /usr/local/sbin/magitrickle-local.sh 755 || return 1
    install_text_atomic "$(asset_path init/magitrickle-local)" \
        /etc/init.d/magitrickle-local 755 || return 1

    # Keep the saved toggle value on upgrades.
    if [ ! -f /etc/config/magitrickle-local ]; then
        install_text_atomic "$(asset_path config/magitrickle-local)" \
            /etc/config/magitrickle-local 644 || return 1
    fi

    /etc/init.d/magitrickle-local enable >/dev/null 2>&1 || true

    # fw4 rejects locally generated packets leaving via Mihomo when the zone
    # output policy is REJECT. Nothing is routed there unless a mark is set.
    local zone changed=0
    zone=$(uci show firewall 2>/dev/null | sed -n "s/^firewall\.\([^.]*\)\.name='Mihomo'$/\1/p" | head -1)
    if [ -n "$zone" ] && [ "$(uci -q get "firewall.$zone.output")" != "ACCEPT" ]; then
        uci -q set "firewall.$zone.output=ACCEPT"
        uci commit firewall 2>/dev/null || true
        changed=1
    fi
    [ "$changed" -eq 1 ] && /etc/init.d/firewall reload >/dev/null 2>&1 || true

    return 0
}
